        if remaining_lines == 0:
            return 1 if remaining_bugs == 0 else 0
        if i == n:
            return 0
        ways = 0
        for j in range(remaining_lines // a[i] + 1):
            ways += count_ways(i + 1, remaining_lines - j * a[i], remaining_bugs - j)
