from collections import defaultdict

def count_good_plans(n, m, b, mod):
    dp = [[defaultdict(int) for _ in range(m+1)] for _ in range(n+1)]
    dp[0][0] = {0}

    for i in range(1, n+1):
        for j in range(m+1):
            for k in range(j+1):
                for l in range(b+1):
                    if k + i <= j and l + i * dp[i-1][j-k][l] <= b:
                        dp[i][j][l] += dp[i-1][j-k][l]
                        dp[i][j][l] %= mod

    return sum(dp[n][m].values()) % mod

